    dts_MKT_TP_CD_M.DataID = encodeURI(url);
    dts_MKT_TP_CD_M.reset();
    dts_MKT_TP_CD_M.insertRow(0);
    dts_MKT_TP_CD_M.setCellData(1, "IDX_MKT_CLSS_ID", "");
    dts_MKT_TP_CD_M.setCellData(1, "IDX_MKT_CLSS_NM", "전체");
    cmb_MKT_TP_CD_M.setSelectedIndex(0);

    /* 기초시장 소분류 */
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=ETF_ETN_MKT_TP_CD_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstsrch.mkt.tp.cd.S.select.list.condition";
    dts_MKT_TP_CD_S.DataID = encodeURI(url);
    dts_MKT_TP_CD_S.reset();
    dts_MKT_TP_CD_S.insertRow(0);
    dts_MKT_TP_CD_S.setCellData(1, "IDX_MKT_CLSS_ID", "");
    dts_MKT_TP_CD_S.setCellData(1, "IDX_MKT_CLSS_NM", "전체");
    cmb_MKT_TP_CD_S.setSelectedIndex(0);

    /* 기초자산 대분류 */
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=ETF_ETN_ULY_TP_CD_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstsrch.uly.tp.cd.L.select.list.condition";
    dts_ULY_TP_CD_L.DataID = encodeURI(url);
    dts_ULY_TP_CD_L.reset();
    dts_ULY_TP_CD_L.insertRow(0);
    dts_ULY_TP_CD_L.setCellData(1, "IDX_ASST_CLSS_ID", "");
    dts_ULY_TP_CD_L.setCellData(1, "IDX_ASST_CLSS_NM", "전체");
    cmb_ULY_TP_CD_L.setSelectedIndex(0);

    /* 기초자산 중분류 */
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=ETF_ETN_ULY_TP_CD_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstsrch.uly.tp.cd.M.select.list.condition";
    dts_ULY_TP_CD_M.DataID = encodeURI(url);
    dts_ULY_TP_CD_M.reset();
    dts_ULY_TP_CD_M.insertRow(0);
    dts_ULY_TP_CD_M.setCellData(1, "IDX_ASST_CLSS_ID", "");
    dts_ULY_TP_CD_M.setCellData(1, "IDX_ASST_CLSS_NM", "전체");
    cmb_ULY_TP_CD_M.setSelectedIndex(0);

    /* 기초자산 소분류 */
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=ETF_ETN_ULY_TP_CD_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstsrch.uly.tp.cd.S.select.list.condition";
    dts_ULY_TP_CD_S1.DataID = encodeURI(url);
    dts_ULY_TP_CD_S1.reset();
    dts_ULY_TP_CD_S1.insertRow(0);
    dts_ULY_TP_CD_S1.setCellData(1, "IDX_ASST_CLSS_ID", "");
