    cmb_ULY_TP_CD_S1.setSelectedIndex(0);
};


/*
 기초지수 조회
*/
scwin.fn_list_sync = function() {
    if (dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID") == "") {
        scwin.gIDX_MKT_CLSS_ID = "______";
    } else {
        if (dts_MKT_TP_CD_M.getCellData(dts_MKT_TP_CD_M.getRowPosition(), "IDX_MKT_CLSS_ID") == "") {
            scwin.gIDX_MKT_CLSS_ID = dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID").substr(0, 2) + "____";
        } else {
            if (dts_MKT_TP_CD_S.getCellData(dts_MKT_TP_CD_S.getRowPosition(), "IDX_MKT_CLSS_ID") == "") {
                scwin.gIDX_MKT_CLSS_ID = dts_MKT_TP_CD_M.getCellData(dts_MKT_TP_CD_M.getRowPosition(), "IDX_MKT_CLSS_ID").substr(0, 4) + "__";
            } else {
                scwin.gIDX_MKT_CLSS_ID = dts_MKT_TP_CD_S.getCellData(dts_MKT_TP_CD_S.getRowPosition(), "IDX_MKT_CLSS_ID");
            }
        }
    }
    if (dts_ULY_TP_CD_L.getCellData(dts_ULY_TP_CD_L.getRowPosition(), "IDX_ASST_CLSS_ID") == "") {
        scwin.gIDX_ASST_CLSS_ID = "______";
    } else {
        if (dts_ULY_TP_CD_M.getCellData(dts_ULY_TP_CD_M.getRowPosition(), "IDX_ASST_CLSS_ID") == "") {
            scwin.gIDX_ASST_CLSS_ID = dts_ULY_TP_CD_L.getCellData(dts_ULY_TP_CD_L.getRowPosition(), "IDX_ASST_CLSS_ID").substr(0, 2) + "____";
        } else {
            if (dts_ULY_TP_CD_S1.getCellData(dts_ULY_TP_CD_S1.getRowPosition(), "IDX_ASST_CLSS_ID") == "") {
                scwin.gIDX_ASST_CLSS_ID = dts_ULY_TP_CD_M.getCellData(dts_ULY_TP_CD_M.getRowPosition(), "IDX_ASST_CLSS_ID").substr(0, 4) + "__";
            } else {
                scwin.gIDX_ASST_CLSS_ID = dts_ULY_TP_CD_S1.getCellData(dts_ULY_TP_CD_S1.getRowPosition(), "IDX_ASST_CLSS_ID");
            }
        }
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=ETF_ETN_BYTP_BAS_IDX_ADM_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstsrch.bytp.basidx.adm.select.list.condition" + "&{P}param01=" + $c.stf.getObjectValue(edt_Date) + // 조회일자
        "&{P}param02=" + $c.stf.getObjectValue(edt_Date) + // 조회일자
        "&{P}param03=" + $c.stf.getObjectValue(edt_Date) + // 조회일자
        "&{P}param04=" + $c.stf.getObjectValue(edt_Date) + // 조회일자
        "&{P}param05=" + $c.stf.getObjectValue(edt_Date) + // 조회일자
        "&{P}param06=" + $c.stf.getObjectValue(edt_Date) + // 조회일자
        "&{P}param07=" + $c.stf.getObjectValue(edt_Date) + // 조회일자		
        "&{P}param08=" + $c.stf.getObjectValue(edt_Date) + // 조회일자	
        "&{P}param09=" + $c.stf.getObjectValue(edt_Date) + // 조회일자	
        "&{P}param10=" + $c.stf.getObjectValue(edt_Date) + // 조회일자
        "&{P}param11=" + $c.stf.getObjectValue(cmb_IDX_CALC_INST_CD) + // 지수산출기관
        "&{P}param12=" + $c.stf.getObjectValue(cmb_IDX_CALC_INST_CD) + // 지수산출기관
        "&{P}param13=" + scwin.gIDX_MKT_CLSS_ID + // 기초시장
        "&{P}param14=" + scwin.gIDX_ASST_CLSS_ID + // 기초자산
        "&{P}param15=" + scwin.gIDX_ASST_CLSS_ID + // 기초자산
        "&{P}param16=" + $c.stf.getObjectValue(cmb_IDX_LVRG_INVRS_TP_CD) + // 추적배수
        "&{P}param17=" + $c.stf.getObjectValue(cmb_IDX_LVRG_INVRS_TP_CD); // 추적배수	 

    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
    $c.cm.ShowWin(grd_List);
};



/********************************************** 
 * 함수명   : fn_ExcelDown()
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    if (dts_List.getTotalRow() > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
        $c.data.downloadGridViewExcel(grd_List, "유형분류 및 ETF·ETN 지수 관리", "", "3");
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
scwin.cmb_MKT_TP_CD_L_OnSelChange = function() {
    scwin.gIDX_MKT_CLSS_ID_L = dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID");
    dts_MKT_TP_CD_M.UseFilter = true;
    dts_MKT_TP_CD_M.Filter();
    dts_MKT_TP_CD_M.sort("IDX_MKT_CLSS_ID", 0);
    //dts_MKT_TP_CD_M.sort(); // W-Craft 주석처리 
    if (dts_MKT_TP_CD_L.getCellData(dts_MKT_TP_CD_L.getRowPosition(), "IDX_MKT_CLSS_ID") == "") {
        cmb_MKT_TP_CD_M.setSelectedIndex(0);
        cmb_MKT_TP_CD_S.setSelectedIndex(0);
    }
};
scwin.dts_MKT_TP_CD_M_OnFilter = function(row) {
    if (scwin.gIDX_MKT_CLSS_ID_L == "") {
        return true;
    } else {
        if (dts_MKT_TP_CD_M.getCellData(row, "UP_MKT_CLSS_ID") == scwin.gIDX_MKT_CLSS_ID_L || dts_MKT_TP_CD_M.getCellData(row, "IDX_MKT_CLSS_ID") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.cmb_MKT_TP_CD_M_OnSelChange = function() {
    scwin.gIDX_MKT_CLSS_ID_M = dts_MKT_TP_CD_M.getCellData(dts_MKT_TP_CD_M.getRowPosition(), "IDX_MKT_CLSS_ID");
    dts_MKT_TP_CD_S.UseFilter = true;
