    } else if ((dts_ULY_TP_CD_L.getCellData(dts_ULY_TP_CD_L.getRowPosition(), "IDX_ASST_CLSS_ID") != "") && (dts_ULY_TP_CD_M.getCellData(dts_ULY_TP_CD_M.getRowPosition(), "IDX_ASST_CLSS_ID") == "") &&
